import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易口訣義 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易口訣義 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"classics/koujueyi/011.md","filePath":"classics/koujueyi/011.md"}'),r={name:"classics/koujueyi/011.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>彖曰：小畜，柔得位而上下應之曰「小畜」。健而巽，剛中而志行，乃亨。「密雲不雨」，尚往也。「自我西郊」，施未行也。象曰：風行天上，小畜。君子以懿文德。</p><p>初九：復自道，何其咎，吉。</p><p>象曰：「復自道」，其義吉也。</p><p>九二：牽復，吉。</p><p>象曰：牽覆在中，亦不自失也。</p><p>九三：輿說輻，夫妻反目。</p><p>象曰：「夫妻反目」，不能正室也。</p><p>六四：有孚，血去惕出，無咎。</p><p>象曰：有孚惕出，上合志也。</p><p>九五：有孚攣如，富以其鄰。</p><p>象曰：「有孚攣如」，不獨富也。</p><p>上九：既雨既處，尚德載。婦貞厲。月幾望，君子徵兇。</p><p>象曰：「既雨既處」，德積載也。「君子徵兇」，有所疑也。</p><p>解讀</p><p>「小畜亨」者，畜謂止積制遏之名。乾陽上進，巽體柔順，陽氣上升，陰不能固，所畜微劣，故曰「小畜」，以陽氣得通，故曰「亨」也。「密雲不雨，自我西郊」者，陰既微劣，不能止畜於陽，陽氣上通，雖復至盛密雲而不能施降於雨，但止在西邑之郊而已。亦喻德薄位尊，不能廣其恩惠，所化止於一隅也。象曰「風行天上，小畜」者，風諭恩教之義，風既行於天上，即是教化不及於下，故云「小畜象」也。「君子以懿文德」者，懿，美也；化既不行，可以修美，文德之行，待時乃施也。</p><p>「初九，復自道，何其咎，吉」者，復，反也。處畜之初，畜道未盛，往之於四，無所見閡，猶似反歸之家，何慮咎害，所以「吉」矣。</p><p>「九二，牽復，吉」，牽，挽相連也。畜道未極，猶可牽挽而進，反覆就五，可以吉也。</p><p>「九三，輿說輻，夫妻反目」者，夫小畜之道，先通後畜，至於九三，畜道已成，不可前進，故輿敗輻破，難可以行，故「輿說輻」也。三是陽卦之極，上是陰卦之極，陰而制陽，亦猶女之制夫，室家不正，反目相視，故曰「夫妻反目」也。</p><p>「六四有孚，血去惕出，無咎」者，孚，信也；惕，懼也；血，傷也。九三前進，四塞其路，必被侵傷，故稱「血」也；畏三侵害，故惕懼也。然則上九處物之極，而惡於三，乃得安其位，不被侵傷，遂得血去而畏懼總除也。</p><p>「九五：有孚攣如，富以其鄰」者，二欲上升，而五不相拒也。二牽於五，五又攣二，合信同體，牽攣而行，故曰「有孚攣如」也。五處尊位，富貴昌盛，不獨己有，而與於鄰，鄰謂二也。</p><p>「上九：既雨既處，尚德載。婦貞厲。月幾望，君子徵兇」者，上九雖是陽爻，而統屬陰卦，以上九陰極而致九三之陽，陽不得通，故「既雨」也，不被陽侵而安其位；「既處」也，以陰制陽，是婦制其夫，臣制其君，正之危也，故曰「婦貞厲」。處陰卦之極，積久方顯，其猶人之積尚道德，可以運載於下，故曰「尚德載」也。陰之盛極，如月近望以敵日也，故曰「月幾望」也。處盛極之地，不可以盈，盈而求進，必見侵傷，故君子之行亦兇，故曰「君子徵兇」也。周易口訣義卷一，</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
